pub enum Msg {
    Ping,
    Hello(String),
}

const HELLO_PREFIX: &str = r#"{"v":2,"type":"hello","value":"#;

pub fn decode(bytes: &str) -> Result<Msg, String> {
    if bytes.starts_with(HELLO_PREFIX) {
        let value = &bytes[HELLO_PREFIX.len()..];
        if let Some(value) = value.strip_suffix('}').and_then(parse_json_string) {
            return Ok(Msg::Hello(value));
        }
        return Err("invalid hello envelope".into());
    }

    if bytes == "ping" {
        return Ok(Msg::Ping);
    }

    let error = "unknown";
    eprintln!("decode error: {error}");
    Err(error.into())
}

pub fn encode(msg: &Msg) -> String {
    match msg {
        Msg::Ping => "ping".into(),
        Msg::Hello(value) => format!(
            r#"{{"v":2,"type":"hello","value":"{}"}}"#,
            escape_json_string(value)
        ),
    }
}

fn escape_json_string(value: &str) -> String {
    let mut escaped = String::with_capacity(value.len());
    for character in value.chars() {
        match character {
            '"' => escaped.push_str("\\\""),
            '\\' => escaped.push_str("\\\\"),
            '\n' => escaped.push_str(r#"\n"#),
            '\r' => escaped.push_str(r#"\r"#),
            '\t' => escaped.push_str(r#"\t"#),
            '\u{08}' => escaped.push_str(r#"\b"#),
            '\u{0c}' => escaped.push_str(r#"\f"#),
            character if character.is_control() => {
                escaped.push_str(&format!(r#"\u{:04x}"#, character as u32));
            }
            character => escaped.push(character),
        }
    }
    escaped
}

fn parse_json_string(input: &str) -> Option<String> {
    let mut characters = input.chars();
    if characters.next()? != '"' {
        return None;
    }

    let mut value = String::new();
    while let Some(character) = characters.next() {
        match character {
            '"' => {
                if characters.next().is_some() {
                    return None;
                }
                return Some(value);
            }
            '\\' => match characters.next()? {
                '"' => value.push('"'),
                '\\' => value.push('\\'),
                '/' => value.push('/'),
                'b' => value.push('\u{08}'),
                'f' => value.push('\u{0c}'),
                'n' => value.push('\n'),
                'r' => value.push('\r'),
                't' => value.push('\t'),
                _ => return None,
            },
            character if character.is_control() => return None,
            character => value.push(character),
        }
    }
    None
}

#[cfg(test)]
mod tests {
    use super::*;

    fn encode_roundtrip(msg: Msg) -> Result<Msg, String> {
        decode(&encode(&msg))
    }

    #[test]
    fn ping_encode_roundtrip() {
        assert!(matches!(encode_roundtrip(Msg::Ping), Ok(Msg::Ping)));
    }

    #[test]
    fn hello_uses_v2_envelope() {
        let msg = Msg::Hello("client \"one\"".into());
        assert_eq!(
            encode(&msg),
            r#"{"v":2,"type":"hello","value":"client \"one\""}"#
        );
        assert!(matches!(decode(&encode(&msg)), Ok(Msg::Hello(value)) if value == "client \"one\""));
    }

    #[test]
    fn hello_requires_v2_envelope() {
        assert!(decode(r#"{"type":"hello","value":"client"}"#).is_err());
        assert!(decode(r#"{"v":1,"type":"hello","value":"client"}"#).is_err());
    }
}
